let axiom = "F";
let sentence = axiom;

let rules = [
  {
    a: "F",
    b: "FF+[+F-F-F[-F+F+F]]-[-F+F+F]"
  }
];

let angleDeg = 25;
let angle;

let startLen = 120;
let len;

let generations = 2;

function setup() {
  createCanvas(600, 600);

  angle = radians(angleDeg);
  len = startLen;

  // Generate everything automatically
  for (let i = 0; i < generations; i++) {
    generate();
  }

  noLoop(); // draw only once
}

function draw() {
  turtle();
}

function generate() {
  let nextSentence = "";

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);
    let replaced = false;

    for (let j = 0; j < rules.length; j++) {
      if (current === rules[j].a) {
        nextSentence += rules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) {
      nextSentence += current;
    }
  }

  sentence = nextSentence;
  len *= 0.5;
}

function turtle() {
  background(255);
  resetMatrix();

  translate(width / 2, height);
  stroke(0);
  noFill();

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);

    if (current === "F") {
      line(0, 0, 0, -len);
      translate(0, -len);
    } 
    else if (current === "+") {
      rotate(angle);
    } 
    else if (current === "-") {
      rotate(-angle);
    } 
    else if (current === "[") {
      push();
    } 
    else if (current === "]") {
      pop();
    }
  }
}

