class Cell {
  constructor(x, y, size, active = false) {
    this.x = x;
    this.y = y;
    this.size = size;

    this.active = active;
    this.nextActive = active;

    this.energy = active ? 1 : 0;

    this.phase = random(TWO_PI);
    this.angleOffset = random(TWO_PI);
    this.speed = random(0.5, 1.4);
    this.orbit = random(0.08, 0.22);
    this.drift = random(0.4, 1.2);
    this.particleSize = random(0.18, 0.3);

    this.trail = [];
    this.maxTrailLength = 8;
  }

  setActive(state) {
    this.active = state;
    this.nextActive = state;
  }

  computeNextState(neighborCount) {
    if (this.active) {
      this.nextActive = neighborCount === 2 || neighborCount === 3;
    } else {
      this.nextActive = neighborCount === 3;
    }
  }

  applyNextState() {
    this.active = this.nextActive;
  }

  updateVisual() {
    const target = this.nextActive ? 1 : 0;
    this.energy = lerp(this.energy, target, 0.18);
  }

  updateTrail(px, py) {
    if (this.energy > 0.05) {
      this.trail.push({ x: px, y: py, a: this.energy });
      if (this.trail.length > this.maxTrailLength) {
        this.trail.shift();
      }
    } else {
      if (this.trail.length > 0) {
        this.trail.shift();
      }
    }
  }

  render() {
    this.updateVisual();

    const cx = this.x + this.size * 0.5;
    const cy = this.y + this.size * 0.5;
    const t = frameCount * 0.04 + this.phase;

    const inactiveCol = color(palette[1]);
    const activeCol = color(palette[2]);
    const glowCol = lerpColor(inactiveCol, activeCol, this.energy);

    const orbitR =
      this.size * (this.orbit * (0.3 + 1.2 * this.energy)) +
      sin(t * this.drift) * this.size * 0.04;

    const a = t * this.speed + this.angleOffset;

    const px = cx + cos(a) * orbitR;
    const py = cy + sin(a) * orbitR;

    this.updateTrail(px, py);
    this.renderTrail(glowCol);
    this.renderParticle(px, py, glowCol);
  }

  renderTrail(glowCol) {
    if (this.trail.length < 2) return;

    noFill();

    for (let i = 1; i < this.trail.length; i++) {
      const p0 = this.trail[i - 1];
      const p1 = this.trail[i];

      const amt = i / (this.trail.length - 1);
      const alpha = 10 + 120 * amt * this.energy;

      stroke(red(glowCol), green(glowCol), blue(glowCol), alpha);
      strokeWeight(this.size * (0.04 + 0.08 * amt));
      line(p0.x, p0.y, p1.x, p1.y);
    }

    noStroke();
  }

  renderParticle(px, py, glowCol) {
    const s = this.size * this.particleSize * (0.55 + 1.2 * this.energy);

    noStroke();

    fill(red(glowCol), green(glowCol), blue(glowCol), 24);
    circle(px, py, s * 5);

    fill(red(glowCol), green(glowCol), blue(glowCol), 80);
    circle(px, py, s * 2.3);

    fill(red(glowCol), green(glowCol), blue(glowCol), 255);
    circle(px, py, s);
  }
}

