let maxDepth = 12;

function setup() {
  createCanvas(600, 600);
  rectMode(CENTER);
  noFill();
}

function draw() {
  background(10);

  translate(width / 2, height / 2);

  let root = new Frame(0, 0, 300);

  drawRecursive(root, 0);
}

// ----------------------
// FRAME CLASS
// ----------------------
class Frame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
  }

  draw() {
    stroke(255, 200);
    strokeWeight(2);
    rect(this.x, this.y, this.size);
  }
}

// ----------------------
// RECURSIVE FUNCTION
// ----------------------
function drawRecursive(frame, depth) {
  if (depth > maxDepth) return;

  push();

  // draw current frame
  frame.draw();

  // move + rotate for next level
  rotate(radians(10 + depth * 2));
  translate(frame.size * 0.1, frame.size * 0.1);

  // create smaller frame
  let newSize = frame.size * 0.8;
  let nextFrame = new Frame(0, 0, newSize);

  // recursive call
  drawRecursive(nextFrame, depth + 1);

  pop();
}

let axiom = "F";
let sentence = axiom;

let rules = [
  {
    a: "F",
    b: "FF+[+F-F-F[-F+F+F]]-[-F+F+F]"
  }
];

let angleDeg = 25;
let angle;

let startLen = 120;
let len;

let generations = 2;

function setup() {
  createCanvas(600, 600);

  len = startLen;

  for (let i = 0; i < generations; i++) {
    generate();
  }
}

function draw() {
  angleDeg = map(mouseX, 0, width, 30, 120);
  angle = radians(angleDeg);

  turtle();
}

function generate() {
  let nextSentence = "";

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);
    let replaced = false;

    for (let j = 0; j < rules.length; j++) {
      if (current === rules[j].a) {
        nextSentence += rules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) {
      nextSentence += current;
    }
  }

  sentence = nextSentence;
  len *= 0.5;
}

function turtle() {
  background(255);
  resetMatrix();

  translate(width / 2, height);
  stroke(0);
  noFill();

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);

    if (current === "F") {
      line(0, 0, 0, -len);
      translate(0, -len);
    } else if (current === "+") {
      rotate(angle);
    } else if (current === "-") {
      rotate(-angle);
    } else if (current === "[") {
      push();
    } else if (current === "]") {
      pop();
    }
  }
}

