class BouncingBall {
  constructor(
    x,
    y,
    envWidth,
    envHeight,
    numBalls = 1,
    sizeMultiplier = 1,
    speedMultiplier = 1,
    colorList = []
  ) {
    // current top-left of bounding box
    this.x = x;
    this.y = y;

    // original position
    this.baseX = x;
    this.baseY = y;

    this.envWidth = envWidth;
    this.envHeight = envHeight;

    this.radius = envHeight * 0.02 * sizeMultiplier;

    // local oscillation
    this.t = random(1000);
    this.tx = 0;
    this.ty = 0;
    this.timeSpeed = 0.03;
    this.ampX = envWidth * 0.18;
    this.ampY = envHeight * 0.18;

    // ripple settings
    this.rippleAmp = envWidth * 0.08;
    this.rippleFreq = 0.035;
    this.rippleSpeed = 0.08;
    this.rippleParticleAmp = this.radius * 0.6;

    this.balls = [];

    for (let i = 0; i < numBalls; i++) {
      this.balls.push({
        localOffset: random(1000),
        position: createVector(
          x + random(this.radius, envWidth - this.radius),
          y + random(this.radius, envHeight - this.radius)
        ),
        velocity: createVector(
          random([-1, 1]) * envWidth * 0.01 * speedMultiplier,
          random([-1, 1]) * envHeight * 0.01 * speedMultiplier
        ),
        color:
          colorList.length > 0
            ? colorList[i % colorList.length]
            : color(0)
      });
    }
  }

  update() {
    this.t += this.timeSpeed;

    // --- base oscillation of the cell ---
    let localX = sin(this.t + this.tx) * this.ampX;
    let localY = cos(this.t + this.ty) * this.ampY;

    // --- ripple from bottom-left corner of sketch ---
    const sourceX = 0;
    const sourceY = height;

    const centerX = this.baseX + this.envWidth * 0.5;
    const centerY = this.baseY + this.envHeight * 0.5;

    const d = dist(centerX, centerY, sourceX, sourceY);

    const ripplePhase = d * this.rippleFreq - frameCount * this.rippleSpeed;
    const ripple = sin(ripplePhase);

    // mostly push along x and row-like y
    const rippleX = ripple * this.rippleAmp;
    const rippleY = ripple * this.rippleAmp * 0.35;

    const nextX = this.baseX + localX + rippleX;
    const nextY = this.baseY + localY + rippleY;

    const dx = nextX - this.x;
    const dy = nextY - this.y;

    this.x = nextX;
    this.y = nextY;

    // move all particles with the moving cell
    for (let ball of this.balls) {
      ball.position.x += dx;
      ball.position.y += dy;
    }

    const left = this.x + this.radius;
    const right = this.x + this.envWidth - this.radius;
    const top = this.y + this.radius;
    const bottom = this.y + this.envHeight - this.radius;

    for (let ball of this.balls) {
      // regular bouncing motion
      ball.position.add(ball.velocity);

      // tiny ripple displacement per particle
      const particleRipple =
        sin(ripplePhase + ball.localOffset * 0.01) * this.rippleParticleAmp;

      ball.position.x += particleRipple * 0.08;
      ball.position.y += particleRipple * 0.04;

      // reflect on walls
      if (ball.position.x < left || ball.position.x > right) {
        ball.velocity.x *= -1;
        ball.position.x = constrain(ball.position.x, left, right);
      }

      if (ball.position.y < top || ball.position.y > bottom) {
        ball.velocity.y *= -1;
        ball.position.y = constrain(ball.position.y, top, bottom);
      }
    }
  }

  draw() {
    noStroke();

    for (let ball of this.balls) {
      fill(ball.color);
      circle(ball.position.x, ball.position.y, this.radius * 2);
    }
  }
}

