class Frame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
  }

  draw(depth = 0) {
    let s = this.size;

    // color variation by depth
    stroke(200 + depth * 5, 150, 255, 180);
    strokeWeight(1.5);
    noFill();

    // main circle
    circle(this.x, this.y, s);

    // orbiting circles
    let num = 4;
    let r = s * 0.5;

    for (let i = 0; i < num; i++) {
      let angle = TWO_PI * (i / num);

      let cx = this.x + cos(angle) * r * 0.5;
      let cy = this.y + sin(angle) * r * 0.5;

      circle(cx, cy, s * 0.3);
    }
  }
}

