class Frame {
  constructor({
    x = 0,
    y = 0,
    size = 100,
    rotation = 0,
    drawer = null
  } = {}) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.rotation = rotation;
    this.drawer = drawer;
  }

  render(depth = 0) {
    if (depth > maxDepth) return;

    push();
    translate(this.x, this.y);
    rotate(this.rotation);

    this.drawDebugOutline();
    this.drawNextFrameAnchor();

    if (this.drawer) {
      this.drawer(this, depth);
    }

    let nextFrame = this.createNextFrame(depth);
    if (nextFrame) {
      nextFrame.render(depth + 1);
    }

    pop();
  }

  drawDebugOutline() {
    if (!debugFrame) return;

    push();
    stroke(...debugColor, 220);
    strokeWeight(1);
    noFill();
    drawingContext.setLineDash([5, 5]);
    rect(0, 0, this.size, this.size);
    drawingContext.setLineDash([]);
    pop();
  }

  drawNextFrameAnchor() {
    if (!debugFrame) return;

    let ax = this.size * nextOffsetX;
    let ay = this.size * nextOffsetY;

    push();
    noStroke();
    fill(...debugColor, 220);
    circle(ax, ay, 6);
    pop();
  }

  createNextFrame(depth) {
    let newSize = this.size * scaleFactor;
    if (newSize < 2) return null;

