function drawWobbleGrid(frame, depth) {
  let s = frame.size;
  let t = frameCount * 0.035 + depth * 0.25;

  let cols = 4 + (depth % 4);
  let rows = 4 + (depth % 4);

  let cellW = s / cols;
  let cellH = s / rows;

  for (let gx = 0; gx < cols; gx++) {
    for (let gy = 0; gy < rows; gy++) {
      let px = gx * cellW + cellW * 0.5;
      let py = gy * cellH + cellH * 0.5;

      let phase = t + gx * 0.4 + gy * 0.3;

      let isAlt = (gx + gy) % 2 === 0;
      let adjustedPhase = isAlt ? phase : phase + PI;

      let mixAmt = map(sin(adjustedPhase), -1, 1, 0, 1);
      let col = oscColor(frame.primary, frame.secondary, mixAmt);

      let ew = cellW * (0.3 + 0.5 * abs(sin(phase)));
      let eh = cellH * (0.3 + 0.5 * abs(cos(phase)));

      push();
      translate(px, py);
      rotate(sin(phase) * 0.8);

      noStroke()

      fill(col[0], col[1], col[2], 255);


      ellipse(0, 0, ew, eh);
      pop();
    }
  }
}

