let frame;

function setup() {
  createCanvas(600, 600);
  // Create a frame centered at start, 300px wide
  frame = new InteractiveFrame(width / 2, height / 2, 300);
}

function draw() {
  background(20);
  frame.update();
  frame.display();
}

function mousePressed() {
  frame.pressed();
}

function mouseReleased() {
  frame.released();
}

class InteractiveFrame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.aspectRatio = width / height;
    this.angle = 0;

    this.selected = false;
    this.isResizing = false;
    this.isRotating = false;

    // UI constants
    this.handleSize = 12;
    this.rotateOffset = 40; // Distance of rotate handle above frame
  }

  display() {
    push();
    translate(this.x, this.y);
    rotate(this.angle);

    // 1. Draw the Frame Border
    stroke(this.selected ? '#00ADB5' : 150);
    strokeWeight(this.selected ? 3 : 1);
    noFill();
    rectMode(CENTER);
    rect(0, 0, this.size, this.size / this.aspectRatio);

    if (this.selected) {
      // 2. Draw Corner Resize Handles (Bottom-Right)
      fill(255);
      let hw = this.size / 2;
      let hh = (this.size / this.aspectRatio) / 2;
      rect(hw, hh, this.handleSize, this.handleSize);

      // 3. Draw Rotate Handle
      line(0, -hh, 0, -hh - this.rotateOffset);
      ellipse(0, -hh - this.rotateOffset, this.handleSize, this.handleSize);
    }
    pop();
  }

  update() {
    if (this.isResizing) {
      // Calculate distance from center to mouse, accounting for rotation
      let d = dist(mouseX, mouseY, this.x, this.y);
      this.size = d * 1.414; // Simple approximation to scale based on mouse distance
    }

    if (this.isRotating) {
      this.angle = atan2(mouseY - this.y, mouseX - this.x) + HALF_PI;
    }
  }

  pressed() {
    // Transform mouse coordinates to local space of the frame
    let dx = mouseX - this.x;
    let dy = mouseY - this.y;

    // Reverse rotation to check bounds
    let localX = dx * cos(-this.angle) - dy * sin(-this.angle);
    let localY = dx * sin(-this.angle) + dy * cos(-this.angle);

    let hw = this.size / 2;
    let hh = (this.size / this.aspectRatio) / 2;

    // Check for Rotate Handle (top)
    let distToRotate = dist(localX, localY, 0, -hh - this.rotateOffset);
    if (distToRotate < this.handleSize) {
      this.isRotating = true;
      return;
    }

    // Check for Resize Handle (bottom-right)
    let distToResize = dist(localX, localY, hw, hh);
    if (distToResize < this.handleSize) {
      this.isResizing = true;
      return;
    }

    // Check for Selection (clicking the border area)
    // We check if mouse is near the perimeter
    let innerBuffer = 10;
    let isInside = abs(localX) < hw && abs(localY) < hh;
    let isOutside = abs(localX) > hw + innerBuffer || abs(localY) > hh + innerBuffer;

    if (!isOutside && !isInside) {
      this.selected = true;
    } else if (isInside) {
        // Option: stay selected if clicking inside, or only on border?
        // Current: Select if clicking near the edge
        this.selected = true;
    } else {
      this.selected = false;
    }
  }

  released() {
    this.isResizing = false;
    this.isRotating = false;
  }
}

let frames = [];
let spawnedCircles = [];
let recursionDepth = 5; // How many "layers" deep to go
let drawCalls = 1;      // How many times to repeat the whole recursion per frame

function setup() {
  createCanvas(600, 600);
  // Frame(x, y, size)
  frames.push(new Frame(width / 2, height / 2, 300));
}

function draw() {
  background(15);

  // 1. Draw all user-spawned circles
  noFill();
  stroke(255, 200, 0);
  strokeWeight(2);
  for (let c of spawnedCircles) {
    circle(c.x, c.y, c.r * 2);
  }

  // 2. Update and Draw Frames
  for (let f of frames) {
    f.update();

    // Perform the recursive render for the specified number of draw calls
    for (let i = 0; i < drawCalls; i++) {
      f.display(recursionDepth);
    }
  }
}

function mousePressed() {
  let clickedFrame = false;

  // Check if we are interacting with a frame first
  for (let f of frames) {
    if (f.handlePress(mouseX, mouseY)) {
      clickedFrame = true;
      break; 
    }
  }

  // If no frame was clicked/selected, spawn a circle
  if (!clickedFrame) {
    spawnedCircles.push({ x: mouseX, y: mouseY, r: 20 });
  }
}

function mouseReleased() {
  for (let f of frames) f.handleRelease();
}

