class Frame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.aspectRatio = width / height;
    this.angle = 0;

    this.isSelected = false;
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;

    // Interaction Offsets
    this.offX = 0;
    this.offY = 0;
    this.sizeOffset = 1;

    this.handleSize = 15;
    this.edgeTolerance = 20;

    // Animation State
    this.currentDepth = 0;
    this.timer = 0;
  }

  resetRecursion() {
    this.currentDepth = 0;
    this.timer = 0;
  }

  processRecursion(dest, source) {
    if (this.currentDepth >= maxDepth) return;

    this.timer++;
    if (this.timer >= framesToRender) {
      dest.push();
      dest.translate(this.x, this.y);
      dest.rotate(this.angle);
      dest.imageMode(CENTER);

      let h = this.size / this.aspectRatio;

      // Inject current drawings and existing feedback back into the frame
      dest.image(source, 0, 0, this.size, h);
      dest.image(dest, 0, 0, this.size, h);

      dest.pop();

      this.currentDepth++;
      this.timer = 0;
    }
  }

  update() {
    if (this.isResizing) {
      let d = dist(mouseX, mouseY, this.x, this.y);
      this.size = d * this.sizeOffset;
      if (this.size < 40) this.size = 40; // Prevent inversion
    } else if (this.isRotating) {
      this.angle = atan2(mouseY - this.y, mouseX - this.x);
    } else if (this.isDragging) {
      this.x = mouseX + this.offX;
      this.y = mouseY + this.offY;
    }
  }

