      // Handles
      fill(255);
      stroke(0);
      strokeWeight(1);

      // Resize (Bottom Right)
      rect(hw, hh, this.handleSize, this.handleSize);

      // Rotate (Top Center)
      circle(0, -hh - 25, this.handleSize);

      // Drag (Top Left) - Orange
      fill("#FF5722");
      rect(-hw, -hh, this.handleSize, this.handleSize);
    }
    pop();
  }

  handlePress(mx, my) {
    // Coordinate conversion for rotated space
    let dx = mx - this.x;
    let dy = my - this.y;
    let localX = dx * cos(-this.angle) - dy * sin(-this.angle);
    let localY = dx * sin(-this.angle) + dy * cos(-this.angle);

