let frames = [];
let drawingLayer, feedbackLayer;
let maxDepth = 100, framesToRender = 5;

// Brush State
let brushSize = 40;
let isFilled = false;
let colorPalette = ['#FFC800', '#FF5733', '#C70039', '#900C3F', '#581845', '#2E86C1', '#28B463', '#F4D03F', '#FDFEFE'];
let activeColorIndex = 0;

function setup() {
  createCanvas(600, 600);
  drawingLayer = createGraphics(width, height);
  feedbackLayer = createGraphics(width, height);

  let d = 2;
  pixelDensity(d);
  drawingLayer.pixelDensity(d);
  feedbackLayer.pixelDensity(d);

  drawingLayer.clear();
  feedbackLayer.clear();

  frames.push(new Frame(width * 0.25, height / 2, 150));
  frames.push(new Frame(width * 0.50, height / 2, 150));
  frames.push(new Frame(width * 0.75, height / 2, 150));
}

function draw() {
  background(15);

  let anyActive = frames.some(f => f.isResizing || f.isRotating || f.isDragging);
  let anySelected = frames.some(f => f.isSelected);

  // 1. SMOOTH BRUSH LOGIC
  if (mouseIsPressed && !anyActive && !anySelected) {
    updateDrawing();
    for (let f of frames) f.resetRecursion();
  }

  // 2. GROWTH LOGIC
  if (!anyActive) {
    for (let f of frames) f.processRecursion(feedbackLayer, drawingLayer);
  }

  image(feedbackLayer, 0, 0); 
  image(drawingLayer, 0, 0);  

  for (let f of frames) {
    f.update();
    f.displayUI();
  }

  drawInterface(anyActive || anySelected);
}

function updateDrawing() {
  drawingLayer.stroke(colorPalette[activeColorIndex]);
  drawingLayer.strokeCap(ROUND);
  drawingLayer.strokeJoin(ROUND);

  if (isFilled) {
    // If filled, we draw a thick line to simulate a smooth brush stroke
    drawingLayer.strokeWeight(brushSize);
    drawingLayer.line(pmouseX, pmouseY, mouseX, mouseY);
  } else {
    // If outline, we draw the stroke but it looks better as a series of 
    // circles for the "hollow" recursive effect you like
    drawingLayer.noFill();
    drawingLayer.strokeWeight(2);

    // Interpolation: fill the gaps between frames for smoothness
    let distance = dist(pmouseX, pmouseY, mouseX, mouseY);
    let steps = max(distance / 5, 1); 
    for (let i = 0; i < steps; i++) {
      let lerpX = lerp(pmouseX, mouseX, i / steps);
      let lerpY = lerp(pmouseY, mouseY, i / steps);
      drawingLayer.circle(lerpX, lerpY, brushSize);
    }
  }
}

function drawInterface(hideBrush) {
  if (!hideBrush) {
    noFill();
    stroke(255, 150);
    strokeWeight(1);
    circle(mouseX, mouseY, brushSize);
  }

  // UI Panel
  fill(0, 150);
  noStroke();
  rect(10, height - 100, 240, 90, 5);

  fill(255);
  textSize(11);
  text("DRAG: Paint | [ ] : Size | F : Fill", 20, height - 80);
  text("1-9 : Colors | C : Clear Canvas", 20, height - 65);

  for (let i = 0; i < colorPalette.length; i++) {
    fill(colorPalette[i]);
    stroke(i === activeColorIndex ? 255 : 50);
    strokeWeight(i === activeColorIndex ? 2 : 1);
    rect(20 + i * 22, height - 45, 18, 18, 3);
  }
}

function keyPressed() {
  if (key === '[') brushSize = max(5, brushSize - 5);
  if (key === ']') brushSize = min(300, brushSize + 5);
  if (key === 'f' || key === 'F') isFilled = !isFilled;
  if (key >= '1' && key <= '9') activeColorIndex = int(key) - 1;

  // Clear Canvas Logic
  if (key === 'c' || key === 'C') {
    drawingLayer.clear();
    feedbackLayer.clear();
    for (let f of frames) f.resetRecursion();
  }
}

function mousePressed() {
  for (let i = frames.length - 1; i >= 0; i--) {
    if (frames[i].handlePress(mouseX, mouseY)) {
      let picked = frames.splice(i, 1)[0];
      frames.push(picked);
      break; 
    }
  }
}

function mouseReleased() {
  let needsReset = frames.some(f => f.isDragging || f.isResizing || f.isRotating);
  for (let f of frames) {
    if (needsReset) {
      f.resetRecursion();
      feedbackLayer.clear(); 
    }
    f.handleRelease();
  }
}

