class Frame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.aspectRatio = width / height;
    this.angle = 0;

    this.isSelected = false;
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;

    this.offX = 0;
    this.offY = 0;
    this.sizeOffset = 1;
    this.angleOffset = 0;

    this.handleSize = 16;
    this.edgeTolerance = 20;

    this.currentDepth = 0;
    this.timer = 0;
  }

  resetRecursion() {
    this.currentDepth = 0;
    this.timer = 0;
  }

  processRecursion(dest, source) {
    if (this.currentDepth >= maxDepth) return;

    this.timer++;
    if (this.timer >= framesToRender) {
      dest.push();
      dest.translate(this.x, this.y);
      dest.rotate(this.angle);
      dest.imageMode(CENTER);

      let h = this.size / this.aspectRatio;

      // Draw the source drawings AND the current feedback state into this frame
      dest.image(source, 0, 0, this.size, h);
      dest.image(dest, 0, 0, this.size, h);

      dest.pop();

      this.currentDepth++;
      this.timer = 0;
    }
  }

  update() {
    if (this.isResizing) {
      let d = dist(mouseX, mouseY, this.x, this.y);
      this.size = d * this.sizeOffset;
      this.size = max(this.size, 40);
    } else if (this.isRotating) {
      let currentMouseAngle = atan2(mouseY - this.y, mouseX - this.x);
      this.angle = currentMouseAngle - this.angleOffset;
    } else if (this.isDragging) {
      this.x = mouseX + this.offX;
      this.y = mouseY + this.offY;
    }
  }

  displayUI() {
    push();
    translate(this.x, this.y);
    rotate(this.angle);
    rectMode(CENTER);

    let h = this.size / this.aspectRatio;
    let hw = this.size / 2;
    let hh = h / 2;

    noFill();
    stroke(this.isSelected ? "#00ADB5" : 100);
    strokeWeight(this.isSelected ? 2 : 1);
    rect(0, 0, this.size, h);

    if (this.isSelected) {
      stroke(0);
      strokeWeight(1);

      // Resize (Bottom Right)
      fill(255);
      rect(hw, hh, this.handleSize, this.handleSize);

      // Rotate (Top Center)
      fill(255);
      circle(0, -hh - 30, this.handleSize);

      // Drag (Top Left)
      fill("#FF5722");
      rect(-hw, -hh, this.handleSize, this.handleSize);
    }
    pop();
  }

  handlePress(mx, my) {
    let dx = mx - this.x;
    let dy = my - this.y;
    let localX = dx * cos(-this.angle) - dy * sin(-this.angle);
    let localY = dx * sin(-this.angle) + dy * cos(-this.angle);

    let hw = this.size / 2;
    let hh = (this.size / this.aspectRatio) / 2;

    if (this.isSelected) {
      // 1. Resize
      if (dist(localX, localY, hw, hh) < this.handleSize) {
        this.isResizing = true;
        this.sizeOffset = this.size / dist(mx, my, this.x, this.y);
        return true;
      }
      // 2. Rotate
      if (dist(localX, localY, 0, -hh - 30) < this.handleSize) {
        this.isRotating = true;
        this.angleOffset = atan2(my - this.y, mx - this.x) - this.angle;
        return true;
      }
      // 3. Drag
      if (dist(localX, localY, -hw, -hh) < this.handleSize) {
        this.isDragging = true;
        this.offX = this.x - mx;
        this.offY = this.y - my;
        return true;
      }
    }

    // Border Selection
    let inO = abs(localX) < hw + this.edgeTolerance && abs(localY) < hh + this.edgeTolerance;
    let inI = abs(localX) < hw - this.edgeTolerance && abs(localY) < hh - this.edgeTolerance;

    if (inO && !inI) {
      this.isSelected = true;
      return true;
    }

    this.isSelected = false;
    return false;
  }

  handleRelease() {
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;
  }
}

