let frames = [];
let drawingLayer;

let maxDepth = 100;
let framesToRender = 5;

let brushSize = 50;
let isFilled = false;

let colorPalette = [
  '#a62639', '#db324d', '#56494e', '#a29c9b', '#511c29', '#2E86C1',
  '#28B463', '#F4D03F', '#FDFEFE'
];

let activeColorIndex = 0;
let showHints = true;

let strokes = [];
let currentStroke = [];

// playback state
let isPlayingBackSavedStrokes = false;
let playbackStrokeIndex = 0;
let playbackPointIndex = 0;
let playbackPointsPerFrame = 3;

// Paste saved state here later if you want.
// Example:
// let savedState = {
//   strokes: [...],
//   frames: [
//     { x: 150, y: 300, size: 150, angle: 0 }
//   ]
// };



function setup() {
  createCanvas(600, 600);

  drawingLayer = createGraphics(width, height);
  pixelDensity(2);
  drawingLayer.pixelDensity(2);
  drawingLayer.clear();

  if (typeof savedState !== "undefined") {
    restoreState(savedState);
  } else {
    frames.push(new Frame(width * 0.25, height / 2, 150));
    frames.push(new Frame(width * 0.50, height / 2, 150));
    frames.push(new Frame(width * 0.75, height / 2, 150));
  }
}

function draw() {
  background("#A29C9B");

  if (isPlayingBackSavedStrokes) {
    playbackSavedStrokesStep();
  }

  let anyActive = frames.some(f => f.isResizing || f.isRotating || f.isDragging);

  if (mouseIsPressed && !showHints && !isPlayingBackSavedStrokes) {
    updateDrawing();
    for (let f of frames) f.resetRecursion();
  }

  for (let f of frames) {
    f.update();
  }

  for (let f of frames) {
    f.processRecursion(drawingLayer);
  }

  for (let f of frames) {
    f.drawOutput();
  }

  image(drawingLayer, 0, 0);

  for (let f of frames) {
    f.displayUI();
  }

  drawInterface(anyActive);
}

function updateDrawing() {
  let point = {
    x1: pmouseX,
    y1: pmouseY,
    x2: mouseX,
    y2: mouseY,
    size: brushSize,
    col: colorPalette[activeColorIndex],
    fill: isFilled
  };

  currentStroke.push(point);
  drawPointToLayer(drawingLayer, point);
}

function drawPointToLayer(layer, p) {
  layer.stroke(p.col);
  layer.strokeCap(ROUND);
  layer.strokeJoin(ROUND);

  if (p.fill) {
    layer.strokeWeight(p.size);
    layer.line(p.x1, p.y1, p.x2, p.y2);
  } else {
    layer.noFill();
    layer.strokeWeight(2);

    let distance = dist(p.x1, p.y1, p.x2, p.y2);
    let steps = max(distance / 5, 1);

    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      let lerpX = lerp(p.x1, p.x2, t);
      let lerpY = lerp(p.y1, p.y2, t);
      layer.circle(lerpX, lerpY, p.size);
    }
  }
}

function drawInterface(isBusy) {
  if (isPlayingBackSavedStrokes) {
    fill(255, 180);
    noStroke();
    textSize(12);
    text("Replaying saved drawing...", 10, height - 10);
    return;
  }

  if (!showHints && !isBusy) {
    push();
    if (isFilled) {
      fill(colorPalette[activeColorIndex]);
      noStroke();
    } else {
      noFill();
      stroke(colorPalette[activeColorIndex]);
      strokeWeight(2);
    }
    circle(mouseX, mouseY, brushSize);
    pop();
  }

  if (showHints) {
    fill(0, 200);
    noStroke();
    rect(10, height - 185, 340, 175, 8);

    fill(255);
    textSize(11);
    text("MODE: Layout | H: Artist Mode", 20, height - 165);
    text("A: Spawn Frame | D: Delete Selected", 20, height - 150);
    text("DRAG FRAME: Move | HANDLES: Scale/Rotate", 20, height - 135);
    text("1-9: Colors | [ ]: Size | F: Fill", 20, height - 120);
    text("C: Clear Canvas | Z: Undo Stroke", 20, height - 105);
    text("S: Log state to console", 20, height - 90);

    for (let i = 0; i < colorPalette.length; i++) {
      fill(colorPalette[i]);
      stroke(i === activeColorIndex ? 255 : 80);
      rect(20 + i * 28, height - 60, 22, 22, 4);
    }
  } else {
    fill(255, 80);
    textSize(10);
    text("H for Layout Mode", 10, height - 10);
  }
}

function keyPressed() {
  if (isPlayingBackSavedStrokes) return;

  if (key === '[') brushSize = max(5, brushSize - 5);
  if (key === ']') brushSize = min(400, brushSize + 5);
  if (key === 'f' || key === 'F') isFilled = !isFilled;

  if (key === 'h' || key === 'H') {
    showHints = !showHints;
    for (let f of frames) f.isSelected = false;
  }

  if (key >= '1' && key <= '9') activeColorIndex = int(key) - 1;

  if (key === 'c' || key === 'C') {
    strokes = [];
    currentStroke = [];
    redrawCanvas();
  }

  if (key === 'z' || key === 'Z') {
    strokes.pop();
    redrawCanvas();
  }

  if (key === 's' || key === 'S') {
    logState();
  }

  if (showHints) {
    if (key === 'a' || key === 'A') {
      let nf = new Frame(mouseX, mouseY, 150);
      for (let f of frames) f.isSelected = false;
      nf.isSelected = true;
      frames.push(nf);
    }

    if (key === 'd' || key === 'D') {
      frames = frames.filter(f => !f.isSelected);
    }
  }
}

function logState() {
  let allStrokes = JSON.parse(JSON.stringify(strokes));

  if (currentStroke.length > 0) {
    allStrokes.push(JSON.parse(JSON.stringify(currentStroke)));
  }

  let frameData = frames.map(f => ({
    x: f.x,
    y: f.y,
    size: f.size,
    angle: f.angle
  }));

  let state = {
    strokes: allStrokes,
    frames: frameData
  };

  console.log("---- COPY BELOW ----");
  console.log("let savedState = " + JSON.stringify(state, null, 2) + ";");
  console.log("---- COPY ABOVE ----");
}

function restoreState(state) {
  strokes = [];
  currentStroke = [];
  frames = [];

  let restoredStrokes = [];
  if (state.strokes && Array.isArray(state.strokes)) {
    restoredStrokes = JSON.parse(JSON.stringify(state.strokes));
  }

  if (state.frames && Array.isArray(state.frames) && state.frames.length > 0) {
    for (let f of state.frames) {
      let nf = new Frame(f.x, f.y, f.size);
      nf.angle = f.angle || 0;
      frames.push(nf);
    }
  } else {
    frames.push(new Frame(width * 0.25, height / 2, 150));
    frames.push(new Frame(width * 0.50, height / 2, 150));
    frames.push(new Frame(width * 0.75, height / 2, 150));
  }

  if (restoredStrokes.length > 0) {
    strokes = restoredStrokes;
    startSavedStrokePlayback();
  } else {
    redrawCanvas();
  }
}

function startSavedStrokePlayback() {
  drawingLayer.clear();

  for (let f of frames) {
    f.resetRecursion();
  }

  isPlayingBackSavedStrokes = true;
  showHints = false;
  playbackStrokeIndex = 0;
  playbackPointIndex = 0;
}

function playbackSavedStrokesStep() {
  if (playbackStrokeIndex >= strokes.length) {
    isPlayingBackSavedStrokes = false;
    showHints = true;

    for (let f of frames) {
      f.resetRecursion();
    }
    return;
  }

  let stroke = strokes[playbackStrokeIndex];
  if (!stroke || stroke.length === 0) {
    playbackStrokeIndex++;
    playbackPointIndex = 0;
    return;
  }

  for (let n = 0; n < playbackPointsPerFrame; n++) {
    if (playbackStrokeIndex >= strokes.length) break;

    stroke = strokes[playbackStrokeIndex];

    if (!stroke || playbackPointIndex >= stroke.length) {
      playbackStrokeIndex++;
      playbackPointIndex = 0;
      continue;
    }

    drawPointToLayer(drawingLayer, stroke[playbackPointIndex]);
    playbackPointIndex++;

    for (let f of frames) {
      f.resetRecursion();
    }
  }
}

function redrawCanvas() {
  drawingLayer.clear();

  for (let s of strokes) {
    for (let p of s) {
      drawPointToLayer(drawingLayer, p);
    }
  }

  for (let f of frames) {
    f.resetRecursion();
  }
}

function mousePressed() {
  if (isPlayingBackSavedStrokes) return;

  if (!showHints) {
    currentStroke = [];
    return;
  }

  for (let i = frames.length - 1; i >= 0; i--) {
    if (frames[i].handlePress(mouseX, mouseY)) {
      let picked = frames.splice(i, 1)[0];
      frames.push(picked);
      return;
    }
  }

  for (let f of frames) {
    f.isSelected = false;
  }
}

function mouseReleased() {
  if (isPlayingBackSavedStrokes) return;

  if (!showHints && currentStroke.length > 0) {
    strokes.push(JSON.parse(JSON.stringify(currentStroke)));
    currentStroke = [];
  }

  for (let f of frames) {
    f.handleRelease();
  }
}

