class Frame {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.aspectRatio = width / height;
    this.angle = 0;

    this.isSelected = false;
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;

    this.offX = 0;
    this.offY = 0;
    this.sizeOffset = 1;
    this.angleOffset = 0;

    this.handleSize = 16;
    this.currentDepth = 0;
    this.timer = 0;

    this.buffer = createGraphics(width, height);
    this.snapshot = createGraphics(width, height);

    this.buffer.pixelDensity(2);
    this.snapshot.pixelDensity(2);

    this.buffer.clear();
    this.snapshot.clear();
  }

  resetRecursion() {
    this.currentDepth = 0;
    this.timer = 0;
    this.buffer.clear();
    this.snapshot.clear();
  }

  processRecursion(source, globalSource) {
    if (this.currentDepth >= maxDepth) return;

    this.timer++;
    if (this.timer < framesToRender) return;

    let h = this.size / this.aspectRatio;

    // save previous state of this frame only
    this.snapshot.clear();
    this.snapshot.image(this.buffer, 0, 0);

    this.buffer.push();
    this.buffer.translate(this.x, this.y);
    this.buffer.rotate(this.angle);
    this.buffer.imageMode(CENTER);

    // 1. original drawn strokes
    this.buffer.image(source, 0, 0, this.size, h);

    // 2. this frame's own previous recursive history
    this.buffer.image(this.snapshot, 0, 0, this.size, h);

    // 3. all frame outputs from previous draw cycle
    // this is what makes frames "see" each other
    this.buffer.image(globalSource, 0, 0, this.size, h);

    this.buffer.pop();

    this.currentDepth++;
    this.timer = 0;
  }

  drawOutput() {
    image(this.buffer, 0, 0);
  }

  drawToLayer(layer) {
    layer.image(this.buffer, 0, 0);
  }

  update() {
    if (this.isResizing || this.isRotating || this.isDragging) {
      if (this.isResizing) {
        this.size = dist(mouseX, mouseY, this.x, this.y) * this.sizeOffset;
        this.size = max(this.size, 40);
      } else if (this.isRotating) {
        this.angle = atan2(mouseY - this.y, mouseX - this.x) - this.angleOffset;
      } else if (this.isDragging) {
        this.x = mouseX + this.offX;
        this.y = mouseY + this.offY;
      }

      this.resetRecursion();
    }
  }

  displayUI() {
    if (!showHints) return;

    push();
    translate(this.x, this.y);
    rotate(this.angle);
    rectMode(CENTER);

    let h = this.size / this.aspectRatio;
    let hw = this.size / 2;
    let hh = h / 2;

    noFill();
    stroke(this.isSelected ? "#00ADB5" : 100);
    strokeWeight(this.isSelected ? 2 : 1);
    rect(0, 0, this.size, h);

    if (this.isSelected) {
      fill(255);
      stroke(0);
      strokeWeight(1);
      rect(hw, hh, this.handleSize, this.handleSize);
      circle(0, -hh - 30, this.handleSize);
    }

    pop();
  }

  handlePress(mx, my) {
    let dx = mx - this.x;
    let dy = my - this.y;
    let localX = dx * cos(-this.angle) - dy * sin(-this.angle);
    let localY = dx * sin(-this.angle) + dy * cos(-this.angle);

    let hw = this.size / 2;
    let hh = (this.size / this.aspectRatio) / 2;

    if (this.isSelected) {
      if (dist(localX, localY, hw, hh) < this.handleSize) {
        this.isResizing = true;
        this.sizeOffset = this.size / max(dist(mx, my, this.x, this.y), 0.0001);
        return true;
      }

      if (dist(localX, localY, 0, -hh - 30) < this.handleSize) {
        this.isRotating = true;
        this.angleOffset = atan2(my - this.y, mx - this.x) - this.angle;
        return true;
      }
    }

    if (abs(localX) < hw && abs(localY) < hh) {
      this.isSelected = true;
      this.isDragging = true;
      this.offX = this.x - mx;
      this.offY = this.y - my;
      return true;
    }

    this.isSelected = false;
    return false;
  }

  handleRelease() {
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;
  }
}

