    x: f.x,
    y: f.y,
    size: f.size,
    angle: f.angle
  }));

  let state = {
    strokes: allStrokes,
    frames: frameData
  };

  console.log("---- COPY BELOW ----");
  console.log("let savedState = " + JSON.stringify(state, null, 2) + ";");
  console.log("---- COPY ABOVE ----");
}

