      if (this.isResizing) {
        this.size = dist(mouseX, mouseY, this.x, this.y) * this.sizeOffset;
        this.size = max(this.size, 40);
      } else if (this.isRotating) {
        this.angle = atan2(mouseY - this.y, mouseX - this.x) - this.angleOffset;
      } else if (this.isDragging) {
        this.x = mouseX + this.offX;
        this.y = mouseY + this.offY;
      }

      this.resetRecursion();
    }
  }

  displayUI() {
    if (!showHints) return;

    push();
    translate(this.x, this.y);
    rotate(this.angle);
    rectMode(CENTER);

    let h = this.size / this.aspectRatio;
    let hw = this.size / 2;
    let hh = h / 2;

    noFill();
    stroke(this.isSelected ? "#00ADB5" : 100);
    strokeWeight(this.isSelected ? 2 : 1);
    rect(0, 0, this.size, h);

    if (this.isSelected) {
      fill(255);
      stroke(0);
      strokeWeight(1);
      rect(hw, hh, this.handleSize, this.handleSize);
      circle(0, -hh - 30, this.handleSize);
    }

    pop();
  }

  handlePress(mx, my) {
    let dx = mx - this.x;
    let dy = my - this.y;
    let localX = dx * cos(-this.angle) - dy * sin(-this.angle);
    let localY = dx * sin(-this.angle) + dy * cos(-this.angle);

    let hw = this.size / 2;
    let hh = (this.size / this.aspectRatio) / 2;

    if (this.isSelected) {
      if (dist(localX, localY, hw, hh) < this.handleSize) {
        this.isResizing = true;
        this.sizeOffset = this.size / max(dist(mx, my, this.x, this.y), 0.0001);
        return true;
      }

      if (dist(localX, localY, 0, -hh - 30) < this.handleSize) {
        this.isRotating = true;
        this.angleOffset = atan2(my - this.y, mx - this.x) - this.angle;
        return true;
      }
    }

    if (abs(localX) < hw && abs(localY) < hh) {
      this.isSelected = true;
      this.isDragging = true;
      this.offX = this.x - mx;
      this.offY = this.y - my;
      return true;
    }

    this.isSelected = false;
    return false;
  }

  handleRelease() {
    this.isResizing = false;
    this.isRotating = false;
    this.isDragging = false;
  }
}

