let maxIterations = 100;

function setup() {
  createCanvas(600, 600);
  pixelDensity(1);

  loadPixels();

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {

      // map pixel → complex number
      let a = map(x, 0, width - 1, minRe, maxRe);
      let b = map(y, 0, height - 1, maxIm, minIm);

      // store original c
      let ca = a;
      let cb = b;

      let n = 0;

      // Mandelbrot iteration
      while (n < maxIterations) {
        // z = z^2 + c
        let aa = a * a - b * b;
        let bb = 2 * a * b;

        a = aa + ca;
        b = bb + cb;

        // check escape (|z| > 2 → squared > 4)
        if (a * a + b * b > 4) {
          break;
        }

        n++;
      }

      let index = 4 * (x + y * width);

      // grayscale mapping
      let bright;

      if (n === maxIterations) {
        bright = 0; // inside set → black
      } else {
        bright = map(n, 0, maxIterations, 255, 0);
      }

      pixels[index + 0] = bright;
      pixels[index + 1] = bright;
      pixels[index + 2] = bright;
      pixels[index + 3] = 255;
    }
  }

  updatePixels();
  noLoop();
}

