function renderMandelbrot() {
  loadPixels();

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let c = pixelToComplex(x, y);
      let smooth = mandelbrotEscape(c.a, c.b);
      let col = getColor(smooth);

      let index = 4 * (x + y * width);
      pixels[index + 0] = red(col);
      pixels[index + 1] = green(col);
      pixels[index + 2] = blue(col);
      pixels[index + 3] = 255;
    }
  }

  updatePixels();
}

function pixelToComplex(x, y) {
  let a = map(x, 0, width - 1, minRe, maxRe);
  let b = map(y, 0, height - 1, maxIm, minIm);

  return { a, b };
}

function mandelbrotEscape(ca, cb) {
  let a = 0;
  let b = 0;
  let n = 0;

  while (n < maxIterations) {
    let aa = a * a - b * b;
    let bb = 2 * a * b;

    a = aa + ca;
    b = bb + cb;

    if (a * a + b * b > 4) {
      let mag = sqrt(a * a + b * b);
      let smooth = n + 1 - log(log(mag)) / log(2);
      return smooth;
    }

    n++;
  }

  return null; // inside the set
}

function getColor(smooth) {
  if (smooth === null) {
    return color(0, 0, 0);
  }

  let hueValue = map(smooth, 0, maxIterations, 0, 255);
  hueValue = constrain(hueValue, 0, 255);

  return color(hueValue, 200, 255);
}

