}

function draw() {
}

function mousePressed() {
  if (mouseX < 0 || mouseX >= width || mouseY < 0 || mouseY >= height) return;

  let c = pixelToComplex(mouseX, mouseY);
  zoomAt(c.a, c.b, zoomFactorIn);
  updateIterations();
  renderMandelbrot();
}

function keyPressed() {
  if (key === "z" || key === "Z") {
    let center = getCenter();
    zoomAt(center.a, center.b, zoomFactorOut);
    updateIterations();
    renderMandelbrot();
  }

  if (key === "r" || key === "R") {
    resetView();
    renderMandelbrot();
  }

  if (key === "s" || key === "S") {
    saveCurrentViewToConsole();
  }
}

function renderMandelbrot() {
  loadPixels();

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let c = pixelToComplex(x, y);
      let smooth = mandelbrotEscape(c.a, c.b);
      let col = getColorFromPalette(smooth);

      let index = 4 * (x + y * width);
      pixels[index + 0] = col[0];
      pixels[index + 1] = col[1];
      pixels[index + 2] = col[2];
      pixels[index + 3] = 255;
    }
  }

  updatePixels();
}

function pixelToComplex(x, y) {
  let a = map(x, 0, width - 1, minRe, maxRe);
  let b = map(y, 0, height - 1, maxIm, minIm);
  return { a, b };
}

function mandelbrotEscape(ca, cb) {
  let a = 0;
  let b = 0;
  let n = 0;

  while (n < maxIterations) {
    let aa = a * a - b * b;
    let bb = 2 * a * b;

    a = aa + ca;
    b = bb + cb;

    if (a * a + b * b > 4) {
      let mag = sqrt(a * a + b * b);
      let smooth = n + 1 - log(log(mag)) / log(2);
      return smooth;
    }

    n++;
  }

  return null;
}

function getColorFromPalette(smooth) {
  if (smooth === null) {
    return paletteRGB[0];
  }

  if (paletteRGB.length === 1) {
    return paletteRGB[0];
  }

  if (paletteRGB.length === 2) {
    return paletteRGB[1];
  }

  let escapedColors = paletteRGB.slice(1);

  let t = map(smooth, 0, maxIterations, 1, 0);
  t = constrain(t, 0, 1);

  return samplePalette(escapedColors, t);
}

function samplePalette(colors, t) {
  if (colors.length === 1) {
    return colors[0];
  }

  let scaled = t * (colors.length - 1);
  let indexA = floor(scaled);
  let indexB = min(indexA + 1, colors.length - 1);
  let amt = scaled - indexA;

  let c1 = colors[indexA];
  let c2 = colors[indexB];

  return [
    lerp(c1[0], c2[0], amt),
    lerp(c1[1], c2[1], amt),
    lerp(c1[2], c2[2], amt)
  ];
}

function normalizePalette(inputPalette) {
  let result = [];

  for (let i = 0; i < inputPalette.length; i++) {
    result.push(parseColor(inputPalette[i]));
  }

  return result;
}

function parseColor(value) {
  if (Array.isArray(value)) {
    return [value[0], value[1], value[2]];
  }

  if (typeof value === "string") {
    return hexToRgb(value);
  }

  return [0, 0, 0];
}

function hexToRgb(hex) {
  let clean = hex.replace("#", "").trim();

  if (clean.length === 3) {
    clean = clean[0] + clean[0] + clean[1] + clean[1] + clean[2] + clean[2];
  }

  let r = parseInt(clean.substring(0, 2), 16);
  let g = parseInt(clean.substring(2, 4), 16);
  let b = parseInt(clean.substring(4, 6), 16);

  return [r, g, b];
}

function zoomAt(centerRe, centerIm, factor) {
  let reSpan = (maxRe - minRe) * factor;
  let imSpan = (maxIm - minIm) * factor;

  minRe = centerRe - reSpan / 2;
  maxRe = centerRe + reSpan / 2;
  minIm = centerIm - imSpan / 2;
  maxIm = centerIm + imSpan / 2;
}

function getCenter() {
  return {
    a: (minRe + maxRe) * 0.5,
    b: (minIm + maxIm) * 0.5
  };
}

function updateIterations() {
  let initialSpan = viewSettings.maxRe - viewSettings.minRe;
  let currentSpan = maxRe - minRe;
  let zoomLevel = initialSpan / currentSpan;

  maxIterations = floor(baseIterations + log(zoomLevel) * 20);
  maxIterations = max(baseIterations, maxIterations);
}

function resetView() {
  minRe = viewSettings.minRe;
  maxRe = viewSettings.maxRe;
  minIm = viewSettings.minIm;
  maxIm = viewSettings.maxIm;
  baseIterations = viewSettings.baseIterations;
  maxIterations = baseIterations;
}

function saveCurrentViewToConsole() {
  let saved = {
    minRe: minRe,
    maxRe: maxRe,
    minIm: minIm,
    maxIm: maxIm,
    baseIterations: maxIterations
  };

  console.log("let viewSettings = " + JSON.stringify(saved, null, 2) + ";");
}

let axiom = "F";
let sentence = axiom;

let rules = [
  {
    a: "F",
    b: "FF+[+F-F-F[-F+F+F]]-[-F+F+F]"
  }
];

let angleDeg = 25;
let angle;

let startLen = 120;
let len;

let generations = 2;

function setup() {
  createCanvas(600, 600);

  angle = radians(angleDeg);
  len = startLen;

  for (let i = 0; i < generations; i++) {
    generate();
  }

  noLoop();
}

function draw() {
  background(245);
  turtle();
}

function generate() {
  let nextSentence = "";

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);
    let replaced = false;

    for (let j = 0; j < rules.length; j++) {
      if (current === rules[j].a) {
        nextSentence += rules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) {
      nextSentence += current;
    }
  }

  sentence = nextSentence;
  len *= 0.5;
}

function turtle() {
  resetMatrix();
  translate(width / 2, height);

  let firstStemDrawn = false;
  let alternateMode = 0; // 0 = thin branch, 1 = leaf

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);

    if (current === "F") {
      if (!firstStemDrawn) {
        drawSegmentedStem(len * 8);
        firstStemDrawn = true;
      } else {
        if (alternateMode === 0) {
          drawThinBranch(len);
          translate(0, -len);
        } else {
          drawLeaf(len * 1.8);
          translate(0, -len * 0.7);
        }

        alternateMode = 1 - alternateMode;
      }
    } else if (current === "+") {
      rotate(angle);
    } else if (current === "-") {
      rotate(-angle);
    } else if (current === "[") {
      push();
    } else if (current === "]") {
      pop();
    }
  }
}

function drawSegmentedStem(totalLen) {
  let segments = 8;
  let segLen = totalLen / segments;

  stroke(28, 84, 42);
  noFill();

  for (let i = 0; i < segments; i++) {
    strokeWeight(map(i, 0, segments - 1, 10, 4));
    line(0, 0, 0, -segLen);

    translate(0, -segLen);

    strokeWeight(2);
    line(-6, 0, 6, 0);
  }
}

function drawThinBranch(branchLen) {
  stroke(40, 110, 55);
  strokeWeight(1.2);
  noFill();
  line(0, 0, 0, -branchLen);
}

function drawLeaf(leafLen) {
  let side = random() < 0.5 ? -1 : 1;

  push();
  rotate(side * radians(30));

  noStroke();
  fill(50, 130, 65);

  beginShape();
  vertex(0, 0);
  bezierVertex(
    leafLen * 0.25,
    -leafLen * 0.15,
    leafLen * 0.75,
    -leafLen * 0.08,
    leafLen,
    0
  );
  bezierVertex(
    leafLen * 0.75,
    leafLen * 0.08,
    leafLen * 0.25,
    leafLen * 0.15,
    0,
    0
  );
  endShape(CLOSE);

  stroke(35, 95, 48);
  strokeWeight(0.8);
  line(0, 0, leafLen, 0);

  pop();
}

let leafSystem = "X";

let rules = [
  { a: "X", b: "F[+X][-X]FX" },
  { a: "F", b: "FF" }
];

let sentence = "";
let angle;
let stepLen = 10;
let generations = 3;

// which stem nodes should get a leaf/stem L-system
let attachedNodes = [1, 3, 5];

let stemNodes = [];

function setup() {
  createCanvas(600, 600);
  angleMode(RADIANS);
  angle = radians(25);

  sentence = leafSystem;
  for (let i = 0; i < generations; i++) {
    sentence = generate(sentence);
  }

  noLoop();
}

function draw() {
  background(245);

  stemNodes = drawStem(width / 2, height - 40, 7, 60);

  for (let i = 0; i < attachedNodes.length; i++) {
    let nodeIndex = attachedNodes[i];
    if (nodeIndex >= 0 && nodeIndex < stemNodes.length) {
      let node = stemNodes[nodeIndex];
      drawLSystemAt(node.x, node.y, -PI / 4);
    }
  }
}

function generate(str) {
  let next = "";

  for (let i = 0; i < str.length; i++) {
    let ch = str.charAt(i);
    let replaced = false;

    for (let j = 0; j < rules.length; j++) {
      if (ch === rules[j].a) {
        next += rules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) {
      next += ch;
    }
  }

  return next;
}

function drawStem(x, y, segments, segLen) {
  let nodes = [];

  stroke(80, 110, 70);
  strokeWeight(8);
  noFill();

  let currentX = x;
  let currentY = y;

  for (let i = 0; i < segments; i++) {
    let nextY = currentY - segLen;

    // stem segment
    line(currentX, currentY, currentX, nextY);

    // node
    strokeWeight(3);
    line(currentX - 10, nextY, currentX + 10, nextY);

    nodes.push({ x: currentX, y: nextY });

    strokeWeight(8);
    currentY = nextY;
  }

  return nodes;
}

function drawLSystemAt(x, y, baseAngle) {
  push();
  translate(x, y);
  rotate(baseAngle);

  // tiny connector from stem
  stroke(80, 110, 70);
  strokeWeight(2);
  line(0, 0, 8, 0);
  translate(8, 0);

  drawLSystem(sentence, stepLen, angle);
  pop();
}

function drawLSystem(str, len, turnAngle) {
  for (let i = 0; i < str.length; i++) {
    let ch = str.charAt(i);

    if (ch === "F") {
      stroke(60, 120, 60);
      strokeWeight(1.5);
      line(0, 0, len, 0);

      // simple leaf
      push();
      translate(len * 0.6, 0);
      drawLeaf(len * 0.9);
      pop();

      translate(len, 0);

    } else if (ch === "+") {
      rotate(turnAngle);
    } else if (ch === "-") {
      rotate(-turnAngle);
    } else if (ch === "[") {
      push();
    } else if (ch === "]") {
      pop();
    }
  }
}

function drawLeaf(len) {
  noStroke();
  fill(70, 150, 80);

  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.25, -len * 0.12, len * 0.75, -len * 0.08, len, 0);
  bezierVertex(len * 0.75, len * 0.08, len * 0.25, len * 0.12, 0, 0);
  endShape(CLOSE);
}

let branchSystem = "X";

let branchRules = [
  { a: "X", b: "F[+X][-X]FX" },
  { a: "F", b: "FF" }
];

let branchAngle;
let branchStep = 20;
let branchGenerations = 3;

let culmNodes = [];
let attachedNodes = [1, 3, 5];

function setup() {
  createCanvas(600, 600);
