    renderLSystemAtSelectedNode(nodeIndex, dir, 1.0);
  }
}

function generate(str) {
  let next = "";

  for (let i = 0; i < str.length; i++) {
    let current = str.charAt(i);
    let replaced = false;

    for (let j = 0; j < branchRules.length; j++) {
      if (current === branchRules[j].a) {
        next += branchRules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) next += current;
  }

  return next;
}

function renderLSystemAtSelectedNode(nodeIndex, baseAngle, scaleFactor = 1) {
  if (nodeIndex < 0 || nodeIndex >= culmNodes.length) return;

  let node = culmNodes[nodeIndex];

  push();
  translate(node.x, node.y);
  rotate(baseAngle);

  stroke(85, 110, 75, 140);
  strokeWeight(1.2);
  line(0, 0, 6, 0);
  translate(6, 0);

  drawLeafLSystem(branchSystem, branchStep * scaleFactor, branchAngle);
  pop();
}

function drawLeafLSystem(sentence, stepLen, angle) {
  let leafToggle = 0;

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);

    if (current === "F") {
      stroke(80, 110, 70, 130);
      strokeWeight(1);
      line(0, 0, stepLen, 0);

      if (leafToggle % 2 === 0) {
        push();
        translate(stepLen * 0.2, 0);
        drawLeafFan(int(random(4, 6)), stepLen * random(0.9, 1.2));
        pop();
      }

      translate(stepLen, 0);
      leafToggle++;

    } else if (current === "X") {
      if (random() < 0.12) {
        push();
        translate(stepLen * 0.1, 0);
        drawLeafFan(int(random(3, 5)), stepLen * random(0.8, 1.0));
        pop();
      }

    } else if (current === "+") {
      rotate(angle);
    } else if (current === "-") {
      rotate(-angle);
    } else if (current === "[") {
      push();
    } else if (current === "]") {
      pop();
    }
  }
}

function drawLeafFan(count, leafLen) {
  push();

  let spread = radians(70);
  let start = -spread / 2;

  for (let i = 0; i < count; i++) {
    let a = start;
    if (count > 1) {
      a += map(i, 0, count - 1, 0, spread);
    }

    push();
    rotate(a + random(-0.08, 0.08));
    drawLeaf(leafLen * random(0.8, 1.15));
    pop();
  }

  pop();
}

function drawLeaf(len) {
  push();

  rotate(random(-0.06, 0.06));

  noStroke();
  fill(70, 135, 72, 210);

  beginShape();
  vertex(0, 0);
  bezierVertex(
    len * 0.22, -len * 0.10,
    len * 0.68, -len * 0.07,
    len, 0
  );
  bezierVertex(
    len * 0.68, len * 0.07,
    len * 0.22, len * 0.10,
    0, 0
  );
  endShape(CLOSE);

  fill(40, 90, 45, 85);
  beginShape();
  vertex(0, 0);
  bezierVertex(
    len * 0.18, -len * 0.07,
    len * 0.60, -len * 0.04,
    len * 0.92, -len * 0.01
  );
  bezierVertex(
    len * 0.60, 0,
    len * 0.18, len * 0.04,
    0, 0
  );
  endShape(CLOSE);

  stroke(45, 80, 40, 120);
  strokeWeight(1);
  line(0, 0, len, 0);

  pop();
}

function drawBambooCulm(x, yBase, segments, segLen, col, baseThickness) {
  let nodes = [];

  for (let i = 0; i < segments; i++) {
    let yTop = yBase - (i + 1) * segLen;
    let yBottom = yBase - i * segLen;

    let t = i / max(1, segments - 1);
    let thick = lerp(baseThickness, baseThickness * 0.72, t);

    drawCulmSegment(x, yBottom, yTop, thick, col);
    drawNodeBand(x, yTop, thick);

    nodes.push({ x: x, y: yTop });
  }

  return nodes;
}

function drawCulmSegment(x, yBottom, yTop, thick, col) {
  let len = yBottom - yTop;

  push();

  noStroke();
  fill(red(col), green(col), blue(col), alpha(col));

  beginShape();
  vertex(x - thick / 2, yBottom);
  bezierVertex(
    x - thick * 0.48, yBottom - len * 0.33,
    x - thick * 0.42, yBottom - len * 0.66,
    x - thick * 0.35, yTop
  );
  vertex(x + thick * 0.35, yTop);
  bezierVertex(
    x + thick * 0.42, yBottom - len * 0.66,
    x + thick * 0.48, yBottom - len * 0.33,
    x + thick / 2, yBottom
  );
  endShape(CLOSE);

  stroke(255, 120);
  strokeWeight(1);
  line(x - thick * 0.18, yBottom - 4, x - thick * 0.1, yTop + 4);

  stroke(70, 60, 40, 90);
  strokeWeight(1);
  line(x - thick / 2, yBottom, x - thick * 0.35, yTop);
  line(x + thick / 2, yBottom, x + thick * 0.35, yTop);

  pop();
}

function drawNodeBand(x, y, thick) {
  push();

  noFill();
  stroke(90, 75, 50, 160);
  strokeWeight(2);
  arc(x, y, thick * 1.1, thick * 0.45, PI, TWO_PI);
  arc(x, y, thick * 1.1, thick * 0.45, 0, PI);

  stroke(255, 90);
  strokeWeight(1);
  arc(x, y - 1, thick * 0.9, thick * 0.22, PI * 1.05, TWO_PI * 0.98);

  pop();
}

function drawPaperWash() {
  noStroke();

