    x - thick * 0.35, yTop
  );
  vertex(x + thick * 0.35, yTop);
  bezierVertex(
    x + thick * 0.42, yBottom - len * 0.66,
    x + thick * 0.48, yBottom - len * 0.33,
    x + thick / 2, yBottom
  );
  endShape(CLOSE);

  stroke(255, 120);
  strokeWeight(1);
  line(x - thick * 0.18, yBottom - 4, x - thick * 0.1, yTop + 4);

  stroke(70, 60, 40, 90);
  strokeWeight(1);
  line(x - thick / 2, yBottom, x - thick * 0.35, yTop);
  line(x + thick / 2, yBottom, x + thick * 0.35, yTop);

  pop();
}

function drawNodeBand(x, y, thick) {
  push();

  noFill();
  stroke(90, 75, 50, 160);
  strokeWeight(2);
  arc(x, y, thick * 1.1, thick * 0.45, PI, TWO_PI);
  arc(x, y, thick * 1.1, thick * 0.45, 0, PI);

  stroke(255, 90);
  strokeWeight(1);
  arc(x, y - 1, thick * 0.9, thick * 0.22, PI * 1.05, TWO_PI * 0.98);

  pop();
}

function drawPaperWash() {
  noStroke();

  for (let i = 0; i < 2500; i++) {
    fill(120, 180, 90, random(8, 18));
    ellipse(random(width), random(height), random(8, 24), random(8, 24));
  }

  for (let i = 0; i < 1200; i++) {
    fill(255, random(8, 18));
    ellipse(random(width), random(height), random(12, 36), random(12, 36));
  }
}

