let systems = [];
let bgSeed = 0;

function setup() {
  createCanvas(600, 600);
  angleMode(RADIANS);
  noLoop();

  generateComposition();
}

function draw() {
  background(235, 242, 223);

  randomSeed(bgSeed);
  drawPaperWash();

  for (let s of systems) {
    drawBambooSystem(s);
  }
}

function mousePressed() {
  generateComposition();
  redraw();
}

function generateComposition() {
  systems = [];
  bgSeed = floor(random(1000000));

  for (let i = 0; i < SYSTEM_COUNT; i++) {
    systems.push(makeBambooSystem());
  }

  systems.sort((a, b) => a.baseX - b.baseX);
}

function makeBambooSystem() {
  let baseX = width * random(SYSTEM_X_MIN, SYSTEM_X_MAX);
  let baseY = height + random(SYSTEM_Y_OFFSET_MIN, SYSTEM_Y_OFFSET_MAX);
  let overallScale = random(SYSTEM_SCALE_MIN, SYSTEM_SCALE_MAX);

  let segmentCount = int(random(SEGMENT_COUNT_MIN, SEGMENT_COUNT_MAX));
  let baseSegLen = random(BASE_SEG_LEN_MIN, BASE_SEG_LEN_MAX) * overallScale;
  let topSegLen = baseSegLen * random(TOP_SEG_RATIO_MIN, TOP_SEG_RATIO_MAX);

  let baseThickness = random(BASE_THICK_MIN, BASE_THICK_MAX) * overallScale;
  let topThickness = baseThickness * random(TOP_THICK_RATIO_MIN, TOP_THICK_RATIO_MAX);

  let curveAmount = random(CURVE_MIN, CURVE_MAX);
  let driftStart = random(DRIFT_START_MIN, DRIFT_START_MAX);
  let driftEnd = random(DRIFT_END_MIN, DRIFT_END_MAX);

  let col = color(
    random(COL_R_MIN, COL_R_MAX),
    random(COL_G_MIN, COL_G_MAX),
    random(COL_B_MIN, COL_B_MAX),
    COL_ALPHA
  );

  let nodes = [];
  let segments = [];

  let drift = 0;
  let xBottom = baseX;
  let yBottom = baseY;

  for (let i = 0; i < segmentCount; i++) {
    let t = i / max(1, segmentCount - 1);

    let segLen = lerp(baseSegLen, topSegLen, t);
    let thick = lerp(baseThickness, topThickness, t);

    let bendStep = map(i, 0, segmentCount - 1, driftStart, driftEnd);
    drift += curveAmount * 0.06 * bendStep;

    let xTop = baseX + drift;
    let yTop = yBottom - segLen;

    segments.push({
      xBottom,
      yBottom,
      xTop,
      yTop,
      thick
    });

    nodes.push({
      x: xTop,
      y: yTop,
      t: t,
      thickness: thick
    });

    xBottom = xTop;
    yBottom = yTop;
  }

  let branches = generateBranches(nodes);

  return {
    baseX,
    baseY,
    col,
    segments,
    nodes,
    branches
  };
}

function generateBranches(nodes) {
  let branches = [];

  for (let i = 0; i < nodes.length; i++) {
    let node = nodes[i];

    if (node.t < BRANCH_START_T) continue;

    let countChoice = random();
    let attachCount = 0;

    if (countChoice < ATTACH_0_PROB) {
      attachCount = 0;
    } else if (countChoice < ATTACH_0_PROB + ATTACH_1_PROB) {
      attachCount = 1;
    } else {
      attachCount = 2;
    }

    for (let k = 0; k < attachCount; k++) {
      let side;

      if (attachCount === 1) {
        side = random() < 0.5 ? -1 : 1;
      } else {
        side = k === 0 ? -1 : 1;
      }

      let generations = int(random(GENERATION_MIN, GENERATION_MAX + 1));
      let systemString = buildLSystem("F", generations);

      let baseAngle;
      if (side < 0) {
        baseAngle = random(BASE_ANGLE_LEFT_MIN, BASE_ANGLE_LEFT_MAX);
      } else {
        baseAngle = random(BASE_ANGLE_RIGHT_MIN, BASE_ANGLE_RIGHT_MAX);
      }

      let stepLen =
        map(node.t, BRANCH_START_T, 1, STEP_LEN_BOTTOM, STEP_LEN_TOP) *
        random(0.9, 1.15);

      let branchAngle = radians(random(BRANCH_ANGLE_MIN, BRANCH_ANGLE_MAX));
      let connectorScale = map(
        node.t,
        BRANCH_START_T,
        1,
        CONNECTOR_SCALE_BOTTOM,
        CONNECTOR_SCALE_TOP
      );

      branches.push({
        x: node.x,
        y: node.y,
        baseAngle,
        stepLen,
        branchAngle,
        connectorScale,
        systemString
      });
    }
  }

  return branches;
}

function drawBambooSystem(system) {
  for (let seg of system.segments) {
    drawCulmSegment(
      seg.xBottom,
      seg.yBottom,
      seg.xTop,
      seg.yTop,
      seg.thick,
      system.col
    );
    drawNodeBand(seg.xTop, seg.yTop, seg.thick);
  }

  for (let branch of system.branches) {
    push();
    translate(branch.x, branch.y);
    rotate(branch.baseAngle);

    stroke(85, 110, 75, 140);
    strokeWeight(1.2);
    line(0, 0, 6 * branch.connectorScale, 0);
    translate(6 * branch.connectorScale, 0);

    drawLeafLSystem(branch.systemString, branch.stepLen, branch.branchAngle);
    pop();
  }
}

function buildLSystem(axiom, generations) {
  let str = axiom;

  for (let i = 0; i < generations; i++) {
    str = generate(str);
  }

  return str;
}

function generate(str) {
  let next = "";

  for (let i = 0; i < str.length; i++) {
    let current = str.charAt(i);
    let replaced = false;

    for (let j = 0; j < branchRules.length; j++) {
      if (current === branchRules[j].a) {
        next += branchRules[j].b;
        replaced = true;
        break;
      }
    }

    if (!replaced) {
      next += current;
    }
  }

  return next;
}

function drawLeafLSystem(sentence, stepLen, angle) {
  let leafToggle = 0;

  for (let i = 0; i < sentence.length; i++) {
    let current = sentence.charAt(i);

    if (current === "F") {
      stroke(80, 110, 70, 130);
      strokeWeight(1);
      line(0, 0, stepLen, 0);

      if (leafToggle % 2 === 0) {
        push();
        translate(stepLen * 0.18, 0);
        drawLeafFan(
          int(random(LEAF_FAN_COUNT_MIN, LEAF_FAN_COUNT_MAX)),
          stepLen * random(LEAF_SIZE_MIN, LEAF_SIZE_MAX)
        );
        pop();
      }

      translate(stepLen * 0.5, 0);
      leafToggle++;

    } else if (current === "+") {
      rotate(angle);
    } else if (current === "-") {
      rotate(-angle);
    } else if (current === "[") {
      push();
    } else if (current === "]") {
      pop();
    }
  }
}

function drawLeafFan(count, leafLen) {
  push();

  let spread = radians(random(LEAF_SPREAD_MIN, LEAF_SPREAD_MAX));
  let start = -spread / 2;

  for (let i = 0; i < count; i++) {
    let a = start;

    if (count > 1) {
      a += map(i, 0, count - 1, 0, spread);
    }

    push();
    rotate(random(LEAF_ROTATION_JITTER_MIN, LEAF_ROTATION_JITTER_MAX) + a);
    drawLeaf(leafLen * random(LEAF_SIZE_MIN, LEAF_SIZE_MAX));
    pop();
  }

  pop();
}

function drawLeaf(len) {
  push();

  rotate(random(SINGLE_LEAF_ROTATION_MIN, SINGLE_LEAF_ROTATION_MAX));

  noStroke();
  fill(70, 135, 72, 210);

  beginShape();
  vertex(0, 0);
  bezierVertex(
    len * 0.22, -len * 0.10,
    len * 0.68, -len * 0.07,
    len, 0
  );
  bezierVertex(
    len * 0.68, len * 0.07,
    len * 0.22, len * 0.10,
    0, 0
  );
  endShape(CLOSE);

  fill(40, 90, 45, 85);
  beginShape();
  vertex(0, 0);
  bezierVertex(
    len * 0.18, -len * 0.07,
    len * 0.60, -len * 0.04,
    len * 0.92, -len * 0.01
  );
  bezierVertex(
    len * 0.60, 0,
    len * 0.18, len * 0.04,
    0, 0
  );
  endShape(CLOSE);

  stroke(45, 80, 40, 120);
  strokeWeight(1);
  line(0, 0, len, 0);

  pop();
}

function drawCulmSegment(xBottom, yBottom, xTop, yTop, thick, col) {
  let len = dist(xBottom, yBottom, xTop, yTop);

  let nx = -(yTop - yBottom) / max(len, 0.0001);
  let ny = (xTop - xBottom) / max(len, 0.0001);

  let bx1x = lerp(xBottom, xTop, 0.33);
  let bx1y = lerp(yBottom, yTop, 0.33);

  let bx2x = lerp(xBottom, xTop, 0.66);
  let bx2y = lerp(yBottom, yTop, 0.66);

  noStroke();
  fill(red(col), green(col), blue(col), alpha(col));

  beginShape();
  vertex(xBottom + nx * thick * 0.5, yBottom + ny * thick * 0.5);
  bezierVertex(
    bx1x + nx * thick * 0.48, bx1y + ny * thick * 0.48,
    bx2x + nx * thick * 0.42, bx2y + ny * thick * 0.42,
    xTop + nx * thick * 0.35, yTop + ny * thick * 0.35
  );
  vertex(xTop - nx * thick * 0.35, yTop - ny * thick * 0.35);
  bezierVertex(
    bx2x - nx * thick * 0.42, bx2y - ny * thick * 0.42,
    bx1x - nx * thick * 0.48, bx1y - ny * thick * 0.48,
    xBottom - nx * thick * 0.5, yBottom - ny * thick * 0.5
  );
  endShape(CLOSE);

  stroke(255, 120);
  strokeWeight(1);
  line(
    xBottom + nx * thick * 0.12,
    yBottom + ny * thick * 0.12,
    xTop + nx * thick * 0.05,
    yTop + ny * thick * 0.05
  );

  stroke(70, 60, 40, 90);
  strokeWeight(1);
  line(
    xBottom + nx * thick * 0.5,
    yBottom + ny * thick * 0.5,
    xTop + nx * thick * 0.35,
    yTop + ny * thick * 0.35
  );
  line(
    xBottom - nx * thick * 0.5,
    yBottom - ny * thick * 0.5,
    xTop - nx * thick * 0.35,
    yTop - ny * thick * 0.35
  );
}

function drawNodeBand(x, y, thick) {
  push();
  translate(x, y);

  noFill();
  stroke(90, 75, 50, 160);
  strokeWeight(2);
  arc(0, 0, thick * 1.1, thick * 0.45, PI, TWO_PI);
  arc(0, 0, thick * 1.1, thick * 0.45, 0, PI);

  stroke(255, 90);
  strokeWeight(1);
  arc(0, -1, thick * 0.9, thick * 0.22, PI * 1.05, TWO_PI * 0.98);

  pop();
}

function drawPaperWash() {
  noStroke();

  for (let i = 0; i < WASH_GREEN_COUNT; i++) {
    fill(120, 180, 90, random(WASH_GREEN_ALPHA_MIN, WASH_GREEN_ALPHA_MAX));
    ellipse(
      random(width),
      random(height),
      random(WASH_GREEN_SIZE_MIN, WASH_GREEN_SIZE_MAX),
      random(WASH_GREEN_SIZE_MIN, WASH_GREEN_SIZE_MAX)
    );
  }

  for (let i = 0; i < WASH_WHITE_COUNT; i++) {
    fill(255, random(WASH_WHITE_ALPHA_MIN, WASH_WHITE_ALPHA_MAX));
    ellipse(
      random(width),
      random(height),
      random(WASH_WHITE_SIZE_MIN, WASH_WHITE_SIZE_MAX),
      random(WASH_WHITE_SIZE_MIN, WASH_WHITE_SIZE_MAX)
    );
  }
}

