class Emitter {
  constructor(x, y, opts = {}) {
    this.x = x;
    this.y = y;
    this.rate = opts.rate ?? 3;
    this.particles = [];
  }

  emit() {
    for (let i = 0; i < this.rate; i++) {
      this.particles.push(
        new Particle(this.x, this.y, {
          size: random(3, 7),
          life: 255
        })
      );
    }
  }

  update(flowField) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      let p = this.particles[i];

      p.follow(flowField);
      p.update();
      p.edges();

      if (p.isDead()) {
        this.particles.splice(i, 1);
      }
    }
  }

  render() {
    for (let p of this.particles) {
      p.render();
    }
  }

  run(flowField) {
    this.emit();
    this.update(flowField);
    this.render();
  }

  setPosition(x, y) {
    this.x = x;
    this.y = y;
  }
}

