class FlowField {
  constructor(resolution) {
    this.resolution = resolution;
    this.cols = floor(width / this.resolution);
    this.rows = floor(height / this.resolution);
    this.field = new Array(this.cols * this.rows);
    this.zoff = 0;
    this.init();
  }

  init() {
    let yoff = 0;
    for (let y = 0; y < this.rows; y++) {
      let xoff = 0;
      for (let x = 0; x < this.cols; x++) {
        let index = x + y * this.cols;

        let angle = noise(xoff, yoff, this.zoff) * TWO_PI * 2;
        let v = p5.Vector.fromAngle(angle);
        v.setMag(0.15);

        this.field[index] = v;
        xoff += 0.08;
      }
      yoff += 0.08;
    }
  }

  update() {
    this.zoff += 0.003;
    this.init();
  }

  lookup(x, y) {
    let col = floor(constrain(x, 0, width - 1) / this.resolution);
    let row = floor(constrain(y, 0, height - 1) / this.resolution);
    let index = col + row * this.cols;
    return this.field[index].copy();
  }

  render() {
    stroke(255, 60);
    strokeWeight(1);

    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x < this.cols; x++) {
        let index = x + y * this.cols;
        let v = this.field[index];

        let px = x * this.resolution;
        let py = y * this.resolution;

        push();
        translate(px, py);
        rotate(v.heading());
        line(0, 0, this.resolution * 0.8, 0);
        pop();
      }
    }
  }
}

