class Emitter {
  constructor(x, y, opts = {}) {
    this.x = x;
    this.y = y;

    this.rate = opts.rate ?? 2;
    this.maxParticles = opts.maxParticles ?? 1000;
    this.hashCellSize = opts.hashCellSize ?? 24;

    this.spawnRadius = opts.spawnRadius ?? 2;
    this.radialSpeedMin = opts.radialSpeedMin ?? 0.8;
    this.radialSpeedMax = opts.radialSpeedMax ?? 2.2;

    this.repulsionRadius = opts.repulsionRadius ?? 80;
    this.repulsionStrength = opts.repulsionStrength ?? 0.12;

    this.particles = [];
    this.palette = opts.palette ?? ["#ffffff"];
  }

  emit() {
    const hex = random(this.palette);
    const col = color(hex); // 👈 convert once here
    for (let i = 0; i < this.rate; i++) {
      if (this.particles.length >= this.maxParticles) break;

      const angle = random(TWO_PI);
      const spawnOffset = p5.Vector.fromAngle(angle).mult(
        random(0, this.spawnRadius),
      );
      const radialVel = p5.Vector.fromAngle(angle).mult(
        random(this.radialSpeedMin, this.radialSpeedMax),
      );

      this.particles.push(
        new Particle(this.x + spawnOffset.x, this.y + spawnOffset.y, {
          vel: radialVel,
          size: random(1, 5),
          life: 250,
          decay: 0.1,
          maxSpeed: 2.5,
          color: col
        }),
      );
    }
  }

  buildSpatialHash() {
    const hash = new Map();

    for (const p of this.particles) {
      const cx = floor(p.pos.x / this.hashCellSize);
      const cy = floor(p.pos.y / this.hashCellSize);
      const key = `${cx},${cy}`;

      if (!hash.has(key)) {
        hash.set(key, []);
      }

      hash.get(key).push(p);
    }

    return hash;
  }

  applyRepulsion(p) {
    const dx = p.pos.x - this.x;
    const dy = p.pos.y - this.y;
    const dSq = dx * dx + dy * dy;
    const radiusSq = this.repulsionRadius * this.repulsionRadius;

    if (dSq > 0 && dSq < radiusSq) {
      const d = sqrt(dSq);
      const force = createVector(dx, dy);

      force.normalize();

      // stronger near center, weaker near edge
      const strength = map(
        d,
        0,
        this.repulsionRadius,
        this.repulsionStrength,
        0,
      );
      force.mult(strength);

      p.applyForce(force);
    }
  }

  update(flowField) {
    const spatialHash = this.buildSpatialHash();

    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];

      p.follow(flowField);
      p.separateFromSpatialHash(spatialHash, this.hashCellSize);
      this.applyRepulsion(p);
      p.update();
      p.edges();

      if (p.isDead()) {
        this.particles.splice(i, 1);
      }
    }
  }

  render() {
    for (const p of this.particles) {
      p.render();
    }
  }

  run(flowField) {
    this.emit();
    this.update(flowField);
    this.render();
  }

  setPosition(x, y) {
    this.x = x;
    this.y = y;
  }
}

