let flowField;
let walkers = [];
let emitters = [];
let cellSize = 20;
let palette = ["#4059ad","#6b9ac4","#97d8c4","#eff2f1","#f4b942"];

let numWalkers = 8;

function setup() {
  createCanvas(600, 600);
  background(20);

  flowField = new FlowField(cellSize);

  for (let i = 0; i < numWalkers; i++) {
    let x = random(width);
    let y = random(height);

    let walker = new PerlinWalker(x, y, {
      xoff: random(1000),
      yoff: random(1000),
      xStep: random(0.0003, 0.0003),
      yStep: random(0.0003, 0.0003),
      speed: random(2, 3)
    });

    let emitter = new Emitter(x, y, {
      rate: 3,
      maxParticles: 2000,
      hashCellSize: 10,
      spawnRadius: 3,
      radialSpeedMin: 1,
      radialSpeedMax: 2.5,
      repulsionRadius: 100,
      repulsionStrength: 8,
      palette: palette
    });

    walkers.push(walker);
    emitters.push(emitter);
  }
}

function draw() {
  background(20, 30);

  if (frameCount % 2 === 0) {
    flowField.update();
  }

  for (let i = 0; i < walkers.length; i++) {
    walkers[i].update();
    emitters[i].setPosition(walkers[i].pos.x, walkers[i].pos.y);
  }

  // gather all particles from all emitters
  let allParticles = [];
  for (let emitter of emitters) {
    allParticles = allParticles.concat(emitter.particles);
  }

  // build one global spatial hash
  let globalSpatialHash = new Map();
  for (const p of allParticles) {
    const cx = floor(p.pos.x / 24);
    const cy = floor(p.pos.y / 24);
    const key = `${cx},${cy}`;
    if (!globalSpatialHash.has(key)) {
      globalSpatialHash.set(key, []);
    }
    globalSpatialHash.get(key).push(p);
  }

  for (let i = 0; i < emitters.length; i++) {
    emitters[i].run(flowField, emitters, globalSpatialHash);
  }

  // optional: show emitter positions
  /*
  noStroke();
  fill(255, 80, 80);
  for (let e of emitters) {
    circle(e.x, e.y, 10);
  }
  */
}

