      spawnRadius: 3,
      radialSpeedMin: 1,
      radialSpeedMax: 2.5,
      repulsionRadius: 25,
      repulsionStrength: 10,
      palette: palette
    });

    walkers.push(walker);
    emitters.push(emitter);
  }
}

function draw() {
  background(20, 30);

  if (frameCount % 2 === 0) {
    flowField.update();
  }

  for (let i = 0; i < walkers.length; i++) {
