let flowField;
let walkers = [];
let emitters = [];
let cellSize = 20;
let palette = ["#e8d7ff","#ffd3e8","#ffd7d5","#f3ffe1","#dfffd6"]

let numWalkers = 20;

function setup() {
  createCanvas(600, 600);
  background(20);

  flowField = new FlowField(cellSize);

  for (let i = 0; i < numWalkers; i++) {
    let x = random(width);
    let y = random(height);

    let walker = new PerlinWalker(x, y, {
      xoff: random(1000),
      yoff: random(1000),
      xStep: random(0.003, 0.0003),
      yStep: random(0.003, 0.0003),
      speed: random(1, 2)
    });

    let emitter = new Emitter(x, y, {
      rate: 5,
      maxParticles: 1000,
      hashCellSize: 10,
      spawnRadius: 3,
      radialSpeedMin: 1,
      radialSpeedMax: 2.5,
      repulsionRadius: 10,
      repulsionStrength: 100,
      palette: palette
    });

    walkers.push(walker);
    emitters.push(emitter);
  }
}

function draw() {
  background("#e194c4");

  if (frameCount % 2 === 0) {
    flowField.update();
  }

  for (let i = 0; i < walkers.length; i++) {
    walkers[i].update();
    emitters[i].setPosition(walkers[i].pos.x, walkers[i].pos.y);
  }

  // emit first
  for (let emitter of emitters) {
    emitter.emit();
  }

  // build global particle list
  let allParticles = [];
  for (let emitter of emitters) {
    allParticles = allParticles.concat(emitter.particles);
  }

  // build one global spatial hash for all particles
  let globalSpatialHash = buildGlobalSpatialHash(allParticles, 24);

  // update + render all emitters using the same hash
  for (let emitter of emitters) {
    emitter.update(flowField, globalSpatialHash);
    emitter.render();
  }
}

function buildGlobalSpatialHash(particles, cellSize) {
  const hash = new Map();

  for (const p of particles) {
    const cx = floor(p.pos.x / cellSize);
    const cy = floor(p.pos.y / cellSize);
    const key = `${cx},${cy}`;

    if (!hash.has(key)) {
      hash.set(key, []);
    }

    hash.get(key).push(p);
  }

  return hash;
}

