class Particle {
  constructor(x, y, opts = {}) {
    this.pos = createVector(x, y);
    this.prevPos = this.pos.copy();

    this.vel = opts.vel ? opts.vel.copy() : p5.Vector.random2D().mult(0.5);
    this.acc = createVector(0, 0);

    this.size = opts.size ?? 1.5;
    this.life = opts.life ?? 250;
    this.maxLife = this.life;
    this.decay = opts.decay ?? 1;
    this.maxSpeed = opts.maxSpeed ?? 2;
    this.color = opts.color ?? color(random(255), random(255), random(255));
  }

  applyForce(force) {
    this.acc.add(force);
  }

  follow(flowField) {
    const force = flowField.lookup(this.pos.x, this.pos.y);
    this.applyForce(force);
  }

  separateFromSpatialHash(spatialHash, cellSize) {
    const desiredSeparation = max(10, this.size * 6);
    const desiredSeparationSq = desiredSeparation * desiredSeparation;

    const cx = floor(this.pos.x / cellSize);
    const cy = floor(this.pos.y / cellSize);

    let steer = createVector(0, 0);
    let count = 0;

    for (let oy = -1; oy <= 1; oy++) {
      for (let ox = -1; ox <= 1; ox++) {
        const key = `${cx + ox},${cy + oy}`;
        const neighbors = spatialHash.get(key);

        if (!neighbors) continue;

        for (const other of neighbors) {
          if (other === this) continue;

          let dx = this.pos.x - other.pos.x;
          let dy = this.pos.y - other.pos.y;
          let dSq = dx * dx + dy * dy;

          if (dSq <= 0.0001 || dSq >= desiredSeparationSq) continue;

          let d = sqrt(dSq);

          // direction away from neighbor
          let diff = createVector(dx, dy).normalize();

          // stronger when closer
          let strength = (desiredSeparation - d) / desiredSeparation;
          diff.mult(strength);

          steer.add(diff);
          count++;

          // direct positional push apart
          let push = diff.copy().mult(0.05);
          this.pos.add(push);
        }
      }
    }

    if (count > 0) {
      steer.div(count);

      if (steer.magSq() > 0) {
        steer.setMag(35); // much stronger than 0.05
        this.applyForce(steer);
      }
    }
  }

  update() {
    this.prevPos.set(this.pos);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);

    this.acc.mult(0);
    this.life -= this.decay;
  }

  render() {
    let c = this.color;

    // size shrinks with life
    let lifeFactor = this.life / this.maxLife;

    fill(red(c), green(c), blue(c)); // no alpha fade
    noStroke();

    let vx = this.vel.x;
    let vy = this.vel.y;
    let mag = Math.hypot(vx, vy);

    if (mag < 0.0001) return;

    let dx = vx / mag;
    let dy = vy / mag;

    let px = -dy;
    let py = dx;

    // shrink size over time
    let s = this.size * lifeFactor;

    let tipX = this.pos.x + dx * s;
    let tipY = this.pos.y + dy * s;

    let backX = this.pos.x - dx * s * 0.6;
    let backY = this.pos.y - dy * s * 0.6;

    let leftX = backX + px * s * 0.5;
    let leftY = backY + py * s * 0.5;

    let rightX = backX - px * s * 0.5;
    let rightY = backY - py * s * 0.5;

    triangle(tipX, tipY, leftX, leftY, rightX, rightY);
  }

