      this.pos.x = width;
      wrapped = true;
    } else if (this.pos.x > width) {
      this.pos.x = 0;
      wrapped = true;
    }

    if (this.pos.y < 0) {
      this.pos.y = height;
      wrapped = true;
    } else if (this.pos.y > height) {
      this.pos.y = 0;
      wrapped = true;
    }

    if (wrapped) {
      this.prevPos.set(this.pos);
    }
  }

  isDead() {
    return this.life <= 0;
  }
}

