class Particle {
  constructor(x, y, opts = {}) {
    this.pos = createVector(x, y);
    this.prevPos = this.pos.copy();

    this.vel = opts.vel ? opts.vel.copy() : p5.Vector.random2D().mult(0.5);
    this.acc = createVector(0, 0);

    this.size = opts.size ?? 1.5;
    this.life = opts.life ?? 250;
    this.maxLife = this.life;
    this.decay = opts.decay ?? 1;
    this.maxSpeed = opts.maxSpeed ?? 2;
    this.color = opts.color ?? color(random(255), random(255), random(255));
  }

  applyForce(force) {
    this.acc.add(force);
  }

  follow(flowField) {
    const force = flowField.lookup(this.pos.x, this.pos.y);
    this.applyForce(force);
  }

  separateFromSpatialHash(spatialHash, cellSize) {
    const desiredSeparation = max(10, this.size * 6);
    const desiredSeparationSq = desiredSeparation * desiredSeparation;

    const cx = floor(this.pos.x / cellSize);
    const cy = floor(this.pos.y / cellSize);

    let steer = createVector(0, 0);
    let count = 0;

    for (let oy = -1; oy <= 1; oy++) {
      for (let ox = -1; ox <= 1; ox++) {
        const key = `${cx + ox},${cy + oy}`;
        const neighbors = spatialHash.get(key);

        if (!neighbors) continue;

        for (const other of neighbors) {
          if (other === this) continue;

          let dx = this.pos.x - other.pos.x;
          let dy = this.pos.y - other.pos.y;
          let dSq = dx * dx + dy * dy;

          if (dSq <= 0.0001 || dSq >= desiredSeparationSq) continue;

          let d = sqrt(dSq);

          // direction away from neighbor
          let diff = createVector(dx, dy).normalize();

          // stronger when closer
          let strength = (desiredSeparation - d) / desiredSeparation;
          diff.mult(strength);

          steer.add(diff);
          count++;

          // direct positional push apart
          let push = diff.copy().mult(0.05);
          this.pos.add(push);
        }
      }
    }

    if (count > 0) {
      steer.div(count);

      if (steer.magSq() > 0) {
        steer.setMag(35); // much stronger than 0.05
        this.applyForce(steer);
      }
    }
  }

  update() {
    this.prevPos.set(this.pos);

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);

    this.acc.mult(0);
    this.life -= this.decay;
  }

  render() {
  if (!cam || cam.pixels.length === 0) return;

  let vx = this.vel.x;
  let vy = this.vel.y;
  let mag = Math.hypot(vx, vy);

  if (mag < 0.0001) return;

  let dx = vx / mag;
  let dy = vy / mag;

  let px = -dy;
  let py = dx;

  // map canvas position to camera pixel position
  let camX = floor(map(this.pos.x, 0, width, cam.width - 1, 0)); 
  let camY = floor(map(this.pos.y, 0, height, 0, cam.height - 1));

  camX = constrain(camX, 0, cam.width - 1);
  camY = constrain(camY, 0, cam.height - 1);

  let index = (camX + camY * cam.width) * 4;

  let r = cam.pixels[index + 0];
  let g = cam.pixels[index + 1];
  let b = cam.pixels[index + 2];

  fill(r, g, b);
  noStroke();

  // keep size constant, stretch based on speed
  let baseSize = this.size * 2.2;
  let speedFactor = constrain(mag / this.maxSpeed, 0, 1);

  let halfLength = lerp(baseSize * 0.7, baseSize * 1.8, speedFactor);
  let halfWidth  = lerp(baseSize * 0.9, baseSize * 0.3, speedFactor);

  let tipX = this.pos.x + dx * halfLength;
  let tipY = this.pos.y + dy * halfLength;

  let backX = this.pos.x - dx * halfLength * 0.7;
  let backY = this.pos.y - dy * halfLength * 0.7;

  let leftX = backX + px * halfWidth;
  let leftY = backY + py * halfWidth;

  let rightX = backX - px * halfWidth;
  let rightY = backY - py * halfWidth;

  triangle(tipX, tipY, leftX, leftY, rightX, rightY);
}

  edges() {
    let wrapped = false;

    if (this.pos.x < 0) {
      this.pos.x = width;
      wrapped = true;
    } else if (this.pos.x > width) {
      this.pos.x = 0;
      wrapped = true;
    }

    if (this.pos.y < 0) {
      this.pos.y = height;
      wrapped = true;
    } else if (this.pos.y > height) {
      this.pos.y = 0;
      wrapped = true;
    }

    if (wrapped) {
      this.prevPos.set(this.pos);
    }
  }

  isDead() {
    return this.life <= 0;
  }
}

